        // Shared composite (0-100). Single source of truth for the per-period score written to
        // domainState.performance.overallScore (reporting/grading layer) AND the debrief. Weights
        // identical to v1.0.0.
        _composite(ds) {
            var eco = Math.round(ds.eco || 0), social = Math.round(ds.social || 0), fit = Math.round(ds.fit || 0), margin = ds.margin || 0;
            return Math.max(0, Math.min(100, Math.round(eco * 0.3 + social * 0.3 + fit * 0.25 + Math.min(100, margin * 5) * 0.15)));
        }

        getPerformanceSummary(history) {
            if (!history.length) return {};
            const ds = window.mySimulation.state.domainState;
            const eco = Math.round(ds.eco), social = Math.round(ds.social), fit = Math.round(ds.fit), margin = ds.margin;

            // The mandate: genuine ecological AND social value while holding EBIT >= 10%.
            const floorHeld = !ds.floorBreached && margin >= this.MARGIN_FLOOR;
            const realImpact = eco >= 55 && social >= 50;
            const composite = this._composite(ds);

            const T = (window.mySimulation && typeof window.mySimulation.t === 'function')
                ? function(k, v) { return window.mySimulation.t(k, v); }
                : function(k) { return k; };

            // Grade band -> localized label (thresholds identical to v1.0.0).
            let performanceKey = `grade_bolton`;
            if (floorHeld && realImpact && fit >= 60 && composite >= 70) performanceKey = `grade_pattern`;
            else if (floorHeld && realImpact && composite >= 58) performanceKey = `grade_credible`;
            else if (floorHeld && composite >= 45) performanceKey = `grade_marginsafe`;
            else if (!floorHeld) performanceKey = `grade_brokefloor`;
            const performance = T(performanceKey);

            const insights = [];
            if (floorHeld && realImpact && fit >= 60) insights.push(window.mySimulation.t(`insight_transformation`));
            else if (floorHeld && !realImpact) insights.push(window.mySimulation.t(`insight_tokenism`));
            else if (!floorHeld) insights.push(window.mySimulation.t(`insight_brokefloor`));
            else insights.push(window.mySimulation.t(`insight_partial`));

            if (social < 45) insights.push(window.mySimulation.t(`insight_socialblank`));
            if (fit < 45) insights.push(window.mySimulation.t(`insight_lowfit`));
            if (ds.patternsPicked && ds.patternsPicked.indexOf(`sellmore`) !== -1) insights.push(window.mySimulation.t(`insight_conflict`));
            if (eco >= 55 && social >= 50 && floorHeld) insights.push(window.mySimulation.t(`insight_tbl`));

            return {
                eco: eco,
                social: social,
                fit: fit,
                margin: margin,
                floorHeld: floorHeld,
                composite: composite,
                totalScore: composite,
                overallScore: composite,
                performanceKey: performanceKey,
                performance: performance,
                insights: insights
            };
        }

        formatCompletionMessage(summary) {
            var T = (window.mySimulation && typeof window.mySimulation.t === 'function')
                ? function(k, v) { return window.mySimulation.t(k, v); }
                : function(k) { return k; };
            var s = summary || {};
            var score = (typeof s.totalScore === 'number') ? s.totalScore
                : (typeof s.composite === 'number' ? s.composite : 0);
            var grade = s.performance || (s.performanceKey ? T(s.performanceKey) : '');
            var held = !!s.floorHeld;
            var badge = held
                ? '<span class="pt-cm-badge pt-cm-yes">' + T('cm_floorheld') + '</span>'
                : '<span class="pt-cm-badge pt-cm-no">' + T('cm_floorbroke') + '</span>';
            var insights = Array.isArray(s.insights) ? s.insights : [];
            var items = insights.map(function(t) { return '<li>' + t + '</li>'; }).join('');
            var metrics = ''
                + '<div class="pt-cm-metric"><span class="pt-cm-mv">' + Math.round(s.eco||0) + '</span><span class="pt-cm-ml">' + T('cm_m_eco') + '</span></div>'
                + '<div class="pt-cm-metric"><span class="pt-cm-mv">' + Math.round(s.social||0) + '</span><span class="pt-cm-ml">' + T('cm_m_social') + '</span></div>'
                + '<div class="pt-cm-metric"><span class="pt-cm-mv">' + Math.round(s.fit||0) + '</span><span class="pt-cm-ml">' + T('cm_m_fit') + '</span></div>'
                + '<div class="pt-cm-metric"><span class="pt-cm-mv">' + (Math.round((s.margin||0)*10)/10) + '%</span><span class="pt-cm-ml">' + T('cm_m_margin') + '</span></div>';
            return ''
                + '<div class="pt-completion">'
                +   '<div class="pt-cm-head">'
                +     '<div class="pt-cm-score">' + score + '<span class="pt-cm-score-max">/100</span></div>'
